@page { margin: 72px 44px 54px; } * { box-sizing: border-box; } body { margin: 0; color: #1e3028; font-family: DejaVu Sans, sans-serif; font-size: 10px; line-height: 1.6; } header { position: fixed; top: -52px; left: 0; right: 0; height: 38px; border-bottom: 2px solid #15975e; } .brand { float: left; color: #117a4d; font-size: 16px; font-weight: bold; } .brand b { margin-right: 6px; padding: 4px 7px; border-radius: 5px; color: white; background: #15975e; } .org { float: right; color: #718078; font-size: 8px; text-align: right; } footer { position: fixed; bottom: -35px; left: 0; right: 0; padding-top: 8px; border-top: 1px solid #dfe8e3; color: #7b8982; font-size: 7px; } footer span { float: right; } footer span:after { content: counter(page); } .eyebrow { color: #7542d6; font-size: 8px; font-weight: bold; text-transform: uppercase; } h1 { margin: 5px 0 8px; font-size: 23px; line-height: 1.25; } .badges span { display: inline-block; margin: 0 5px 13px 0; padding: 4px 8px; border-radius: 11px; color: #116f46; background: #e7f7ee; font-size: 7px; text-transform: uppercase; } .route { width: 100%; margin: 10px 0 19px; border-collapse: collapse; } .route td { width: 50%; padding: 11px; border: 1px solid #dfe8e3; } .route small { display: block; color: #7d8983; font-size: 7px; text-transform: uppercase; } .route strong { font-size: 10px; } .summary { padding: 12px 14px; border-left: 3px solid #7542d6; color: #4c5e55; background: #faf8ff; } .body { margin-top: 19px; white-space: pre-line; } .period { margin-top: 22px; padding-top: 10px; border-top: 1px solid #e1e8e4; color: #75837c; font-size: 8px; }
